50 #pragma once
51 #ifndef AI_VERTEX_H_INC
52 #define AI_VERTEX_H_INC
53 
54 #ifdef __GNUC__
55 #   pragma GCC system_header
56 #endif
57 
58 #include <assimp/vector3.h>
59 #include <assimp/mesh.h>
60 #include <assimp/ai_assert.h>
61 
62 #include <functional>
63 
64 namespace Assimp    {
65 
67     // std::plus-family operates on operands with identical types - we need to
68     // support all the (vectype op float) combinations in vector maths.
69     // Providing T(float) would open the way to endless implicit conversions.
71     namespace Intern {
72         template <typename T0, typename T1, typename TRES = T0> struct plus {
73             TRES operator() (const T0& t0, const T1& t1) const {
74                 return t0+t1;
75             }
76         };
77         template <typename T0, typename T1, typename TRES = T0> struct minus {
78             TRES operator() (const T0& t0, const T1& t1) const {
79                 return t0-t1;
80             }
81         };
82         template <typename T0, typename T1, typename TRES = T0> struct multiplies {
83             TRES operator() (const T0& t0, const T1& t1) const {
84                 return t0*t1;
85             }
86         };
87         template <typename T0, typename T1, typename TRES = T0> struct divides {
88             TRES operator() (const T0& t0, const T1& t1) const {
89                 return t0/t1;
90             }
91         };
92     }
93 
94 // ------------------------------------------------------------------------------------------------
99 // ------------------------------------------------------------------------------------------------
100 class Vertex {
101     friend Vertex operator + (const Vertex&,const Vertex&);
102     friend Vertex operator - (const Vertex&,const Vertex&);
103     friend Vertex operator * (const Vertex&,ai_real);
104     friend Vertex operator / (const Vertex&,ai_real);
105     friend Vertex operator * (ai_real, const Vertex&);
106 
107 public:
108     Vertex() {}
109 
110     // ----------------------------------------------------------------------------
112     explicit Vertex(const aiMesh* msh, unsigned int idx) {
113         ai_assert(idx < msh->mNumVertices);
114         position = msh->mVertices[idx];
115 
116         if (msh->HasNormals()) {
117             normal = msh->mNormals[idx];
118         }
119 
120         if (msh->HasTangentsAndBitangents()) {
121             tangent = msh->mTangents[idx];
122             bitangent = msh->mBitangents[idx];
123         }
124 
125         for (unsigned int i = 0; msh->HasTextureCoords(i); ++i) {
126             texcoords[i] = msh->mTextureCoords[i][idx];
127         }
128 
129         for (unsigned int i = 0; msh->HasVertexColors(i); ++i) {
130             colors[i] = msh->mColors[i][idx];
131         }
132     }
133 
134     // ----------------------------------------------------------------------------
136     explicit Vertex(const aiAnimMesh* msh, unsigned int idx) {
137         ai_assert(idx < msh->mNumVertices);
138         if (msh->HasPositions()) {
139             position = msh->mVertices[idx];
140         }
141 
142         if (msh->HasNormals()) {
143             normal = msh->mNormals[idx];
144         }
145 
146         if (msh->HasTangentsAndBitangents()) {
147             tangent = msh->mTangents[idx];
148             bitangent = msh->mBitangents[idx];
149         }
150 
151         for (unsigned int i = 0; msh->HasTextureCoords(i); ++i) {
152             texcoords[i] = msh->mTextureCoords[i][idx];
153         }
154 
155         for (unsigned int i = 0; msh->HasVertexColors(i); ++i) {
156            colors[i] = msh->mColors[i][idx];
157         }
158     }
159 
160     Vertex& operator += (const Vertex& v) {
161         *this = *this+v;
162         return *this;
163     }
164 
165     Vertex& operator -= (const Vertex& v) {
166         *this = *this-v;
167         return *this;
168     }
169 
170     Vertex& operator *= (ai_real v) {
171         *this = *this*v;
172         return *this;
173     }
174 
175     Vertex& operator /= (ai_real v) {
176         *this = *this/v;
177         return *this;
178     }
179 
180     // ----------------------------------------------------------------------------
182     void SortBack(aiMesh* out, unsigned int idx) const {
183         ai_assert(idx<out->mNumVertices);
184         out->mVertices[idx] = position;
185 
186         if (out->HasNormals()) {
187             out->mNormals[idx] = normal;
188         }
189 
190         if (out->HasTangentsAndBitangents()) {
191             out->mTangents[idx] = tangent;
192             out->mBitangents[idx] = bitangent;
193         }
194 
195         for(unsigned int i = 0; out->HasTextureCoords(i); ++i) {
196             out->mTextureCoords[i][idx] = texcoords[i];
197         }
198 
199         for(unsigned int i = 0; out->HasVertexColors(i); ++i) {
200             out->mColors[i][idx] = colors[i];
201         }
202     }
203 
204 private:
205 
206     // ----------------------------------------------------------------------------
208     template <template <typename t> class op> static Vertex BinaryOp(const Vertex& v0, const Vertex& v1) {
209         // this is a heavy task for the compiler to optimize ... *pray*
210 
211         Vertex res;
212         res.position  = op<aiVector3D>()(v0.position,v1.position);
213         res.normal    = op<aiVector3D>()(v0.normal,v1.normal);
214         res.tangent   = op<aiVector3D>()(v0.tangent,v1.tangent);
215         res.bitangent = op<aiVector3D>()(v0.bitangent,v1.bitangent);
216 
217         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++i) {
218             res.texcoords[i] = op<aiVector3D>()(v0.texcoords[i],v1.texcoords[i]);
219         }
220         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_COLOR_SETS; ++i) {
221             res.colors[i] = op<aiColor4D>()(v0.colors[i],v1.colors[i]);
222         }
223         return res;
224     }
225 
226     // ----------------------------------------------------------------------------
228     template <template <typename, typename, typename> class op> static Vertex BinaryOp(const Vertex& v0, ai_real f) {
229         // this is a heavy task for the compiler to optimize ... *pray*
230 
231         Vertex res;
232         res.position  = op<aiVector3D,ai_real,aiVector3D>()(v0.position,f);
233         res.normal    = op<aiVector3D,ai_real,aiVector3D>()(v0.normal,f);
234         res.tangent   = op<aiVector3D,ai_real,aiVector3D>()(v0.tangent,f);
235         res.bitangent = op<aiVector3D,ai_real,aiVector3D>()(v0.bitangent,f);
236 
237         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++i) {
238             res.texcoords[i] = op<aiVector3D,ai_real,aiVector3D>()(v0.texcoords[i],f);
239         }
240         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_COLOR_SETS; ++i) {
241             res.colors[i] = op<aiColor4D,ai_real,aiColor4D>()(v0.colors[i],f);
242         }
243         return res;
244     }
245 
246     // ----------------------------------------------------------------------------
248     template <template <typename, typename, typename> class op> static Vertex BinaryOp(ai_real f, const Vertex& v0) {
249         // this is a heavy task for the compiler to optimize ... *pray*
250 
251         Vertex res;
252         res.position  = op<ai_real,aiVector3D,aiVector3D>()(f,v0.position);
253         res.normal    = op<ai_real,aiVector3D,aiVector3D>()(f,v0.normal);
254         res.tangent   = op<ai_real,aiVector3D,aiVector3D>()(f,v0.tangent);
255         res.bitangent = op<ai_real,aiVector3D,aiVector3D>()(f,v0.bitangent);
256 
257         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++i) {
258             res.texcoords[i] = op<ai_real,aiVector3D,aiVector3D>()(f,v0.texcoords[i]);
259         }
260         for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_COLOR_SETS; ++i) {
261             res.colors[i] = op<ai_real,aiColor4D,aiColor4D>()(f,v0.colors[i]);
262         }
263         return res;
264     }
265 
266 public:
267 
268     aiVector3D position;
269     aiVector3D normal;
270     aiVector3D tangent, bitangent;
271 
272     aiVector3D texcoords[AI_MAX_NUMBER_OF_TEXTURECOORDS];
273     aiColor4D colors[AI_MAX_NUMBER_OF_COLOR_SETS];
274 };
275 
276 // ------------------------------------------------------------------------------------------------
277 AI_FORCE_INLINE Vertex operator + (const Vertex& v0,const Vertex& v1) {
278     return Vertex::BinaryOp<std::plus>(v0,v1);
279 }
280 
281 AI_FORCE_INLINE Vertex operator - (const Vertex& v0,const Vertex& v1) {
282     return Vertex::BinaryOp<std::minus>(v0,v1);
283 }
284 
285 AI_FORCE_INLINE Vertex operator * (const Vertex& v0,ai_real f) {
286     return Vertex::BinaryOp<Intern::multiplies>(v0,f);
287 }
288 
289 AI_FORCE_INLINE Vertex operator / (const Vertex& v0,ai_real f) {
290     return Vertex::BinaryOp<Intern::multiplies>(v0,1.f/f);
291 }
292 
293 AI_FORCE_INLINE Vertex operator * (ai_real f,const Vertex& v0) {
294     return Vertex::BinaryOp<Intern::multiplies>(f,v0);
295 }
296 
297 }
298 
299 #endif // AI_VERTEX_H_INC
